func rpc_decodeRpcError(value any) (*rpc_RpcError, bool) {
	data, ok := rpc_asBytes(value)
	if !ok || len(data) == 0 {
		return nil, false
	}
	var rpcErr rpc_RpcError
	if rest, err := rpc_readRpcError(data, &rpcErr); err == nil && len(rest) == 0 {
		return &rpcErr, true
	}
	if data[0] == 1 {
		if rest, err := rpc_readRpcError(data[1:], &rpcErr); err == nil && len(rest) == 0 {
			return &rpcErr, true
		}
	}
	return nil, false
}

func rpc_decodeReplyError(value any, method string) (*rpc_RpcError, bool) {
	data, ok := rpc_asBytes(value)
	if !ok || len(data) == 0 || data[0] != 1 {
		return nil, false
	}
	var rpcErr rpc_RpcError
	rest, err := rpc_readRpcError(data[1:], &rpcErr)
	if err != nil || len(rest) != 0 {
		return nil, false
	}
	if rpcErr.Method == "" {
		rpcErr.Method = method
	}
	return &rpcErr, true
}

// Socket.IO carries the ack timeout as a flag mutated on the socket and
// consumed by the next Emit, so two concurrent calls on one connection can
// steal each other's timeout. Every emit the generated code performs is
// serialized through the per-socket lock below to keep that pairing intact.
type rpc_socketEmitState struct {
	mu   sync.Mutex
	refs int
}

var rpc_socketEmitStates = struct {
	sync.Mutex
	states map[*sioclient.Socket]*rpc_socketEmitState
}{states: make(map[*sioclient.Socket]*rpc_socketEmitState)}

func rpc_acquireSocketEmitState(rawSocket *sioclient.Socket) *rpc_socketEmitState {
	rpc_socketEmitStates.Lock()
	defer rpc_socketEmitStates.Unlock()
	shared := rpc_socketEmitStates.states[rawSocket]
	if shared == nil {
		shared = &rpc_socketEmitState{}
		rpc_socketEmitStates.states[rawSocket] = shared
	}
	shared.refs++
	return shared
}

func rpc_releaseSocketEmitState(rawSocket *sioclient.Socket, shared *rpc_socketEmitState) {
	if rawSocket == nil || shared == nil {
		return
	}
	rpc_socketEmitStates.Lock()
	defer rpc_socketEmitStates.Unlock()
	if rpc_socketEmitStates.states[rawSocket] != shared {
		return
	}
	shared.refs--
	if shared.refs == 0 {
		delete(rpc_socketEmitStates.states, rawSocket)
	}
}

type rpc_eventQueue struct {
	run func([]any)

	mu      sync.Mutex
	pending [][]any
	running bool
}

func rpc_newEventQueue(run func([]any)) *rpc_eventQueue {
	return &rpc_eventQueue{run: run}
}

// push never blocks: the Socket.IO listener must stay free to deliver the
// next packet even while this method's handler is still running.
func (q *rpc_eventQueue) push(args []any) {
	q.mu.Lock()
	q.pending = append(q.pending, args)
	if q.running {
		q.mu.Unlock()
		return
	}
	q.running = true
	q.mu.Unlock()
	go q.drain()
}

func (q *rpc_eventQueue) drain() {
	for {
		q.mu.Lock()
		if len(q.pending) == 0 {
			q.running = false
			q.mu.Unlock()
			return
		}
		next := q.pending[0]
		q.pending = q.pending[1:]
		q.mu.Unlock()
		q.run(next)
	}
}

// queuedListener gives one event its own queue. Building it here rather than
// in rpc_bindClient keeps the registration site free of per-method locals, so the
// only contract-derived identifiers in that scope are struct field selectors.
func rpc_queuedListener(run func([]any)) func(...any) {
	queue := rpc_newEventQueue(run)
	return func(rawArgs ...any) {
		queue.push(append([]any(nil), rawArgs...))
	}
}

// sessionListener gives one event its own queue and hands each call the
// context of the connection it arrived on, captured on arrival: a call that
// waits in the queue across a reconnect still belongs to the old connection.
func rpc_sessionListener(conn *Conn, run func(context.Context, []any)) func(...any) {
	queue := rpc_newEventQueue(func(event []any) {
		ctx, _ := event[0].(context.Context)
		args, _ := event[1].([]any)
		run(ctx, args)
	})
	return func(rawArgs ...any) {
		queue.push([]any{conn.sessionContext(), append([]any(nil), rawArgs...)})
	}
}

type ClientHandler interface {
	HandleRunTask(ctx context.Context, task wire.Task) (wire.TaskResult, error)
	HandleCancelTask(ctx context.Context, taskID string) error
}

type rpc_clientBinding struct {
	rpc_socket    *sioclient.Socket
	rpc_emitState *rpc_socketEmitState
	rpc_handler   ClientHandler
	rpc_ctx       context.Context
	rpc_cancel    context.CancelFunc
	rpc_conn      *Conn

	rpc_mu               sync.RWMutex
	rpc_disposed         bool
	rpc_errorObservers   []rpc_errorSubscription
	rpc_errorObserverSeq uint64
	rpc_disposeOnce      sync.Once

	listenRunTask      func(...any)
	listenCancelTask   func(...any)
	rpc_listenRpcError func(...any)
}

func rpc_bindClient(rawSocket *sioclient.Socket, handler ClientHandler, conn *Conn) (*rpc_clientBinding, error) {
	if rawSocket == nil {
		return nil, rpc_NewRpcError(rpc_CodeInvalidArgument, "socket must not be nil", "Dial", nil)
	}
	if handler == nil {
		return nil, rpc_NewRpcError(rpc_CodeInvalidArgument, "handler must not be nil", "Dial", nil)
	}
	ctx, cancel := context.WithCancel(context.Background())
	binding := &rpc_clientBinding{
		rpc_socket:    rawSocket,
		rpc_emitState: rpc_acquireSocketEmitState(rawSocket),
		rpc_handler:   handler,
		rpc_ctx:       ctx,
		rpc_cancel:    cancel,
		rpc_conn:      conn,
	}

	binding.listenRunTask = rpc_sessionListener(conn, binding.handleRunTask)
	if err := rawSocket.On("runTask", binding.listenRunTask); err != nil {
		binding.Dispose()
		return nil, fmt.Errorf("register runTask: %w", err)
	}
	binding.listenCancelTask = rpc_sessionListener(conn, binding.handleCancelTask)
	if err := rawSocket.On("cancelTask", binding.listenCancelTask); err != nil {
		binding.Dispose()
		return nil, fmt.Errorf("register cancelTask: %w", err)
	}

	// The peer reports a failed fire-and-forget handler out of band, because
	// such a call has no acknowledgement to answer through.
	binding.rpc_listenRpcError = rpc_queuedListener(binding.rpc_handleRpcError)
	if err := rawSocket.On(rpc_RPCErrorEvent, binding.rpc_listenRpcError); err != nil {
		binding.Dispose()
		return nil, fmt.Errorf("register %s: %w", rpc_RPCErrorEvent, err)
	}
	return binding, nil
}

func (b *rpc_clientBinding) Context() context.Context {
	return b.rpc_ctx
}

func (b *rpc_clientBinding) Disposed() bool {
	b.rpc_mu.RLock()
	defer b.rpc_mu.RUnlock()
	return b.rpc_disposed
}

// OnRpcError observes the failures the peer reports out of band: a server
// whose handler for a fire-and-forget client-to-server call fails has no
// acknowledgement to answer through, so it emits the error instead. Without
// an observer here that report is dropped and this side never learns of it.
//
// Observers are additive and run in registration order, matching the
// TypeScript client's onRpcError. Call the returned function to unsubscribe.
func (b *rpc_clientBinding) OnRpcError(handler func(*rpc_RpcError)) func() {
	if b == nil || handler == nil {
		return func() {}
	}
	b.rpc_mu.Lock()
	b.rpc_errorObserverSeq++
	id := b.rpc_errorObserverSeq
	b.rpc_errorObservers = append(b.rpc_errorObservers, rpc_errorSubscription{id: id, fn: handler})
	b.rpc_mu.Unlock()
	return func() {
		b.rpc_mu.Lock()
		defer b.rpc_mu.Unlock()
		for i, sub := range b.rpc_errorObservers {
			if sub.id == id {
				b.rpc_errorObservers = append(b.rpc_errorObservers[:i], b.rpc_errorObservers[i+1:]...)
				return
			}
		}
	}
}

func (b *rpc_clientBinding) rpc_handleRpcError(rawArgs []any) {
	b.rpc_mu.RLock()
	// Snapshot under the lock: an observer is free to subscribe or
	// unsubscribe from inside the callback without deadlocking.
	observers := append([]rpc_errorSubscription(nil), b.rpc_errorObservers...)
	disposed := b.rpc_disposed
	b.rpc_mu.RUnlock()
	if len(observers) == 0 || disposed || len(rawArgs) == 0 {
		return
	}
	failure, ok := rpc_decodeRpcError(rawArgs[0])
	if !ok {
		failure = rpc_NewRpcError(rpc_CodeInternalError, fmt.Sprint(rawArgs[0]), rpc_RPCErrorEvent, nil)
	}
	for _, sub := range observers {
		// An observer that panics must not take the queue goroutine down with
		// it, nor stop the observers registered after it.
		func() {
			defer func() {
				_ = recover()
			}()
			sub.fn(failure)
		}()
	}
}

func (b *rpc_clientBinding) Dispose() {
	if b == nil {
		return
	}
	b.rpc_disposeOnce.Do(func() {
		if b.rpc_emitState != nil {
			b.rpc_emitState.mu.Lock()
			defer b.rpc_emitState.mu.Unlock()
		}
		b.rpc_mu.Lock()
		b.rpc_disposed = true
		// Drop the observers too, so Dispose releases every closure the
		// caller handed over — the same contract as the client's dispose().
		b.rpc_errorObservers = nil
		b.rpc_mu.Unlock()
		b.rpc_cancel()
		if b.rpc_socket != nil && b.listenRunTask != nil {
			b.rpc_socket.RemoveListener("runTask", b.listenRunTask)
		}
		if b.rpc_socket != nil && b.listenCancelTask != nil {
			b.rpc_socket.RemoveListener("cancelTask", b.listenCancelTask)
		}
		if b.rpc_socket != nil && b.rpc_listenRpcError != nil {
			b.rpc_socket.RemoveListener(rpc_RPCErrorEvent, b.rpc_listenRpcError)
		}
		rpc_releaseSocketEmitState(b.rpc_socket, b.rpc_emitState)
	})
}

func (b *rpc_clientBinding) rpc_emitError(err *rpc_RpcError) {
	if err == nil || b.rpc_socket == nil || b.rpc_emitState == nil || b.Disposed() {
		return
	}
	// Data is caller-supplied and may not encode; the report must survive it.
	encoded, encErr := rpc_appendRpcError(nil, err)
	if encErr != nil {
		encoded, _ = rpc_appendRpcError(nil, rpc_NewRpcError(err.Code, err.Message, err.Method, nil))
	}
	b.rpc_emitState.mu.Lock()
	defer b.rpc_emitState.mu.Unlock()
	if !b.rpc_socket.Connected() || b.Disposed() {
		return
	}
	_ = b.rpc_socket.NoBuffer().Emit(rpc_RPCErrorEvent, encoded)
}

type rpc_errorSubscription struct {
	id uint64
	fn func(*rpc_RpcError)
}

type rpc_inboundCall struct {
	binding *rpc_clientBinding
	method  string
	ack     func([]any, error)
	args    []any
	once    sync.Once
}

// beginInbound splits the acknowledgement callback off the raw argument list
// and checks arity. It returns nil when the event cannot be carried any
// further, having already reported why.
func rpc_beginInbound(b *rpc_clientBinding, method string, want int, wantAck bool, rawArgs []any) *rpc_inboundCall {
	pending := &rpc_inboundCall{binding: b, method: method}
	args := rawArgs
	if wantAck {
		if len(args) == 0 {
			b.rpc_emitError(rpc_NewRpcError(rpc_CodeInvalidArgument, "missing acknowledgement callback", method, nil))
			return nil
		}
		callback, isAck := args[len(args)-1].(func([]any, error))
		if !isAck {
			b.rpc_emitError(rpc_NewRpcError(rpc_CodeInvalidArgument, "missing acknowledgement callback", method, nil))
			return nil
		}
		pending.ack = callback
		args = args[:len(args)-1]
	}
	if len(args) != want {
		pending.fail(rpc_CodeInvalidArgument, fmt.Sprintf("expected %d arguments, got %d", want, len(args)))
		return nil
	}
	pending.args = args
	return pending
}

// reply answers exactly once. A fire-and-forget call has no acknowledgement
// slot, so its failures travel on the out-of-band error event instead.
func (c *rpc_inboundCall) reply(value any) {
	if c.ack == nil {
		if failure, ok := value.(*rpc_RpcError); ok {
			c.binding.rpc_emitError(failure)
		}
		return
	}
	payload := rpc_encodeReply(value)
	c.once.Do(func() {
		if c.binding != nil && c.binding.rpc_emitState != nil {
			c.binding.rpc_emitState.mu.Lock()
			defer c.binding.rpc_emitState.mu.Unlock()
		}
		c.ack([]any{payload}, nil)
	})
}

func (c *rpc_inboundCall) fail(code rpc_RpcErrorCode, message string) {
	c.reply(rpc_NewRpcError(code, message, c.method, nil))
}

// recoverPanic is deferred directly by the handler, which is what lets the
// builtin recover see a panic unwinding through it.
func (c *rpc_inboundCall) recoverPanic() {
	if value := recover(); value != nil {
		c.reply(rpc_errorFromPanic(value, c.method))
	}
}

func (c *rpc_inboundCall) ready() bool {
	if c.binding.Disposed() {
		c.fail(rpc_CodeDisposed, "connection is disposed")
		return false
	}
	return true
}

func (c *rpc_inboundCall) decode(index int, target any, name string) bool {
	if err := rpc_decodeValue(c.args[index], target); err != nil {
		c.fail(rpc_CodeInvalidArgument, fmt.Sprintf("invalid argument %s: %v", name, err))
		return false
	}
	return true
}

func (c *rpc_inboundCall) finish(value any, err error) {
	if err != nil {
		c.reply(rpc_errorFromError(err, c.method))
		return
	}
	// A reply too large for the server is this handler's failure, not the
	// caller's, so it answers as one instead of closing the connection.
	if failure := c.binding.rpc_conn.checkPayload(c.method, []any{value}); failure != nil {
		failure.Code = rpc_CodeInternalError
		c.reply(failure)
		return
	}
	c.reply(value)
}

func (c *rpc_inboundCall) finishVoid(err error) {
	if err != nil {
		c.reply(rpc_errorFromError(err, c.method))
	}
}

func (b *rpc_clientBinding) handleRunTask(ctx context.Context, rawArgs []any) {
	call := rpc_beginInbound(b, "runTask", 1, true, rawArgs)
	if call == nil {
		return
	}
	defer call.recoverPanic()
	if !call.ready() {
		return
	}
	var arg0 rpc_Task
	if !call.decode(0, &arg0, "task") {
		return
	}
	call.finish(b.rpc_handler.HandleRunTask(ctx, arg0))
}

func (b *rpc_clientBinding) handleCancelTask(ctx context.Context, rawArgs []any) {
	call := rpc_beginInbound(b, "cancelTask", 1, false, rawArgs)
	if call == nil {
		return
	}
	defer call.recoverPanic()
	if !call.ready() {
		return
	}
	var arg0 string
	if !call.decode(0, &arg0, "taskId") {
		return
	}
	call.finishVoid(b.rpc_handler.HandleCancelTask(ctx, arg0))
}

// DialOptions configures one connection. The zero value joins the default
// namespace with no auth payload and the generated default call timeout.
type DialOptions struct {
	// Namespace is the Socket.IO namespace to join, "/" when empty. The address
	// passed to Dial carries no path of its own.
	Namespace string
	// Auth is sent in the CONNECT packet of every attempt, reconnects included.
	// Dial copies the map, so later changes to it are not seen.
	Auth map[string]any
	// Timeout bounds each acknowledged call; zero means the generated default.
	Timeout time.Duration
	// Manager configures the transport: transports, TLS, headers, path and the
	// reconnection backoff. Dial copies it and always turns AutoConnect off.
	// Without transports set here, Dial connects over WebSocket alone.
	Manager sioclient.ManagerOptionsInterface
}

// lifecycleSubscription is one OnConnect or OnDisconnect registration. The
// id is what unsubscribe removes by, as for OnRpcError.
type rpc_lifecycleSubscription struct {
	id         uint64
	connect    func()
	disconnect func(string)
}

// Conn is one connection to the server: the calls this side makes, the
// handler that answers the server's calls, and the reconnecting socket both
// travel over. Dial creates it and Dispose ends it.
type Conn struct {
	socket    *sioclient.Socket
	emitState *rpc_socketEmitState
	binding   *rpc_clientBinding
	namespace string
	timeout   time.Duration
	lifecycle *rpc_eventQueue

	mu sync.RWMutex

	// live is true between a connect and the next disconnect. session is the
	// context of the latest connection, derived from Context(); endSession
	// cancels it when that connection drops.
	disposed    bool
	live        bool
	session     context.Context
	endSession  context.CancelFunc
	err         *rpc_RpcError
	lastError   string
	observers   []rpc_lifecycleSubscription
	observerSeq uint64
	done        chan struct{}
	doneOnce    sync.Once
	dialed      chan struct{}
	dialOnce    sync.Once
	disposeOnce sync.Once

	listenConnect         func(...any)
	listenDisconnect      func(...any)
	listenConnectError    func(...any)
	listenReconnectFailed func(...any)
}

// Dial connects to the server at address, an http, https, ws or wss URL, and
// returns once the namespace has accepted the connection. It keeps retrying
// an unreachable server until ctx ends, so a worker may start before the
// server it serves.
//
// A handshake the server refuses returns at once, as a DISCONNECTED *RpcError
// carrying the server's message. A ctx that ends first returns TIMEOUT or
// ABORTED, naming the last connect error seen.
//
// Once connected the socket reconnects by itself, sending Auth again each
// time; handler keeps answering throughout. Use OnConnect to repeat whatever
// the server should hear after each reconnect.
func Dial(ctx context.Context, address string, handler ClientHandler, options *DialOptions) (*Conn, error) {
	if err := rpc_errorFromContext(ctx, "Dial"); err != nil {
		return nil, err
	}
	if options == nil {
		options = &DialOptions{}
	}
	if options.Timeout < 0 {
		return nil, rpc_NewRpcError(rpc_CodeInvalidArgument, "timeout must not be negative", "Dial", nil)
	}
	namespace := options.Namespace
	if namespace == "" {
		namespace = "/"
	}
	if namespace[0] != '/' {
		return nil, rpc_NewRpcError(rpc_CodeInvalidArgument, fmt.Sprintf("namespace %q must start with /", namespace), "Dial", nil)
	}
	parsed, err := url.Parse(address)
	if err != nil {
		return nil, rpc_NewRpcError(rpc_CodeInvalidArgument, fmt.Sprintf("invalid address: %v", err), "Dial", nil)
	}
	switch parsed.Scheme {
	case "http", "https", "ws", "wss":
	default:
		return nil, rpc_NewRpcError(rpc_CodeInvalidArgument, fmt.Sprintf("address %q must use http, https, ws or wss", address), "Dial", nil)
	}
	if parsed.Path != "" && parsed.Path != "/" {
		return nil, rpc_NewRpcError(rpc_CodeInvalidArgument, fmt.Sprintf("address %q has the path %q; set DialOptions.Namespace instead", address, parsed.Path), "Dial", nil)
	}
	timeout := 5000 * time.Millisecond
	if options.Timeout > 0 {
		timeout = options.Timeout
	}

	// Dial owns its Manager rather than sharing one from the package cache, so
	// the socket and the Manager's reconnect_failed belong to this Conn alone.
	managerOptions := sioclient.DefaultManagerOptions()
	managerOptions.Assign(options.Manager)
	managerOptions.SetAutoConnect(false)
	// A server-to-server connection gains nothing from starting on HTTP
	// long-polling and upgrading: one WebSocket is the whole session.
	if managerOptions.Transports() == nil {
		managerOptions.SetTransports(sioclient.WebSocketOnly())
	}
	socketOptions := sioclient.DefaultSocketOptions()
	if options.Auth != nil {
		auth := make(map[string]any, len(options.Auth))
		for key, value := range options.Auth {
			auth[key] = value
		}
		socketOptions.SetAuth(auth)
	}
	rawSocket := sioclient.NewManager(address, managerOptions).Socket(namespace, socketOptions)

	conn := &Conn{
		socket:    rawSocket,
		emitState: rpc_acquireSocketEmitState(rawSocket),
		namespace: namespace,
		timeout:   timeout,
		done:      make(chan struct{}),
		dialed:    make(chan struct{}),
	}
	conn.lifecycle = rpc_newEventQueue(conn.notify)
	binding, err := rpc_bindClient(rawSocket, handler, conn)
	if err != nil {
		rpc_releaseSocketEmitState(rawSocket, conn.emitState)
		return nil, err
	}
	conn.binding = binding
	// There is no connection before the first connect, so a call cannot arrive
	// under one; the session it would see is already over.
	conn.session, conn.endSession = context.WithCancel(binding.Context())
	conn.endSession()
	if err := conn.listen(); err != nil {
		conn.Dispose()
		return nil, err
	}
	rawSocket.Connect()

	select {
	case <-conn.dialed:
		return conn, nil
	case <-conn.done:
		failure := conn.stateError("Dial")
		conn.Dispose()
		return nil, failure
	case <-ctx.Done():
		failure := rpc_errorFromContext(ctx, "Dial")
		conn.mu.RLock()
		last := conn.lastError
		conn.mu.RUnlock()
		if last != "" {
			failure.Message = fmt.Sprintf("%s; last connect error: %s", failure.Message, last)
		}
		conn.Dispose()
		return nil, failure
	}
}

// OnConnect registers fn to run after every reconnect from now on; the first
// connect has happened by the time Dial returns. To announce something the
// server must hear on every connection, register fn first and then call it
// once yourself: it is never missed, and at worst sent twice.
//
// Observers are additive, run in registration order off the socket's
// goroutines, and may make calls. Call the returned function to unsubscribe.
func (c *Conn) OnConnect(fn func()) func() {
	if c == nil || fn == nil {
		return func() {}
	}
	return c.observe(rpc_lifecycleSubscription{connect: fn})
}

// OnDisconnect registers fn to run once each time the connection goes down,
// with the reason Socket.IO gave. Calls in flight have already failed.
func (c *Conn) OnDisconnect(fn func(reason string)) func() {
	if c == nil || fn == nil {
		return func() {}
	}
	return c.observe(rpc_lifecycleSubscription{disconnect: fn})
}

// OnRpcError observes the failures the server reports out of band: a failed
// handler for a fire-and-forget client-to-server call has no acknowledgement
// to answer through. Call the returned function to unsubscribe.
func (c *Conn) OnRpcError(fn func(*wire.RpcError)) func() {
	if c == nil {
		return func() {}
	}
	return c.binding.OnRpcError(fn)
}

// Connected reports whether the connection is up right now.
func (c *Conn) Connected() bool {
	if c == nil {
		return false
	}
	c.mu.RLock()
	defer c.mu.RUnlock()
	return !c.disposed && c.err == nil && c.live
}

func (c *Conn) isDisposed() bool {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.disposed
}

// Context lives as long as the Conn: Dispose cancels it. Each handler call
// receives a context derived from it for the connection the call arrived on,
// which the loss of that connection also cancels.
func (c *Conn) Context() context.Context {
	return c.binding.Context()
}

// Done is closed by Dispose, or by a loss the socket will not recover from:
// a server-side disconnect, a refused reconnect, or reconnection giving up.
func (c *Conn) Done() <-chan struct{} {
	return c.done
}

// Err is nil until Done is closed, and then why: DISPOSED, or the DISCONNECTED
// loss that ended the connection.
func (c *Conn) Err() error {
	c.mu.RLock()
	defer c.mu.RUnlock()
	if c.err != nil {
		return c.err
	}
	if c.disposed {
		return rpc_NewRpcError(rpc_CodeDisposed, "connection is disposed", "", nil)
	}
	return nil
}

// Socket is the underlying Socket.IO socket, which this Conn owns.
func (c *Conn) Socket() *sioclient.Socket {
	return c.socket
}

// Dispose closes the connection and releases everything Dial set up. Calls in
// flight fail with DISPOSED and handlers see their context cancelled. It is
// safe to call more than once, from any goroutine, a handler included.
func (c *Conn) Dispose() {
	if c == nil {
		return
	}
	c.disposeOnce.Do(func() {
		c.emitState.mu.Lock()
		c.mu.Lock()
		c.disposed = true
		c.observers = nil
		c.mu.Unlock()
		c.doneOnce.Do(func() {
			close(c.done)
		})
		c.emitState.mu.Unlock()
		c.binding.Dispose()
		c.socket.RemoveListener("connect", c.listenConnect)
		c.socket.RemoveListener("disconnect", c.listenDisconnect)
		c.socket.RemoveListener("connect_error", c.listenConnectError)
		c.socket.Io().RemoveListener("reconnect_failed", c.listenReconnectFailed)
		rpc_releaseSocketEmitState(c.socket, c.emitState)
		// Last, and outside every lock: Disconnect runs the socket's listeners
		// synchronously.
		c.socket.Disconnect()
	})
}

// listen registers the lifecycle listeners. They run on the socket's own
// goroutines, so each records the transition and queues what observers see,
// leaving an observer free to make a call.
func (c *Conn) listen() error {
	c.listenConnect = func(...any) { c.handleConnect() }
	c.listenDisconnect = func(args ...any) { c.handleDisconnect(args) }
	c.listenConnectError = func(args ...any) { c.handleConnectError(args) }
	c.listenReconnectFailed = func(...any) { c.terminate("reconnection attempts exhausted") }
	if err := c.socket.On("connect", c.listenConnect); err != nil {
		return fmt.Errorf("register connect: %w", err)
	}
	if err := c.socket.On("disconnect", c.listenDisconnect); err != nil {
		return fmt.Errorf("register disconnect: %w", err)
	}
	if err := c.socket.On("connect_error", c.listenConnectError); err != nil {
		return fmt.Errorf("register connect_error: %w", err)
	}
	if err := c.socket.Io().On("reconnect_failed", c.listenReconnectFailed); err != nil {
		return fmt.Errorf("register reconnect_failed: %w", err)
	}
	return nil
}

func (c *Conn) handleConnect() {
	c.mu.Lock()
	if c.live || c.disposed || c.err != nil {
		c.mu.Unlock()
		return
	}
	c.live = true
	c.session, c.endSession = context.WithCancel(c.binding.Context())
	observers := append([]rpc_lifecycleSubscription(nil), c.observers...)
	c.mu.Unlock()
	c.dialOnce.Do(func() {
		close(c.dialed)
	})
	c.announce(observers, true, "")
}

func (c *Conn) handleDisconnect(args []any) {
	reason := "disconnected"
	if len(args) > 0 {
		if text, ok := args[0].(string); ok && text != "" {
			reason = text
		}
	}
	c.mu.Lock()
	// Socket.IO can report one loss twice; only the transition counts.
	wasLive := c.live
	if wasLive {
		c.live = false
		c.endSession()
	}
	observers := append([]rpc_lifecycleSubscription(nil), c.observers...)
	c.mu.Unlock()
	if wasLive {
		c.announce(observers, false, reason)
	}
	if !c.willReconnect() {
		c.terminate("connection closed: " + reason)
	}
}

func (c *Conn) handleConnectError(args []any) {
	message := "connect error"
	if len(args) > 0 && args[0] != nil {
		if err, ok := args[0].(error); ok {
			message = err.Error()
		} else {
			message = fmt.Sprint(args[0])
		}
	}
	c.mu.Lock()
	c.lastError = message
	c.mu.Unlock()
	// A refused handshake destroys the socket before reporting it, so it will
	// not try again, and the server's message is why the connection ended.
	if !c.willReconnect() {
		c.terminate(message)
	}
}

// willReconnect reports whether the socket will try again after a loss: it
// is still active, which a server-side disconnect or a refused handshake
// ends, and its Manager has reconnection on.
func (c *Conn) willReconnect() bool {
	return c.socket.Active() && c.socket.Io().Reconnection()
}

// terminate ends the connection for good after a loss the socket will not
// recover from. Calls in flight and later ones fail with it as Err.
func (c *Conn) terminate(message string) {
	c.mu.Lock()
	if c.disposed || c.err != nil {
		c.mu.Unlock()
		return
	}
	c.err = rpc_NewRpcError(rpc_CodeDisconnected, message, "", nil)
	c.mu.Unlock()
	c.doneOnce.Do(func() {
		close(c.done)
	})
}

// announce queues one transition for the observers registered when it
// happened, so an observer added afterwards never sees it.
func (c *Conn) announce(observers []rpc_lifecycleSubscription, connected bool, reason string) {
	if len(observers) > 0 {
		c.lifecycle.push([]any{observers, connected, reason})
	}
}

// notify runs on the lifecycle queue, in transition order and off the
// socket's goroutines.
func (c *Conn) notify(event []any) {
	observers, _ := event[0].([]rpc_lifecycleSubscription)
	connected, _ := event[1].(bool)
	reason, _ := event[2].(string)
	for _, sub := range observers {
		if c.isDisposed() {
			return
		}
		// An observer that panics must not stop the ones registered after it.
		func() {
			defer func() {
				_ = recover()
			}()
			if connected && sub.connect != nil {
				sub.connect()
			} else if !connected && sub.disconnect != nil {
				sub.disconnect(reason)
			}
		}()
	}
}

func (c *Conn) observe(sub rpc_lifecycleSubscription) func() {
	c.mu.Lock()
	c.observerSeq++
	id := c.observerSeq
	sub.id = id
	c.observers = append(c.observers, sub)
	c.mu.Unlock()
	return func() {
		c.mu.Lock()
		defer c.mu.Unlock()
		for i, candidate := range c.observers {
			if candidate.id == id {
				c.observers = append(c.observers[:i], c.observers[i+1:]...)
				return
			}
		}
	}
}

// sessionContext is the context of the latest connection: the one an inbound
// call arriving now arrived on. Its loss, or Dispose, cancels it.
func (c *Conn) sessionContext() context.Context {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.session
}

// liveSession returns the channel the current connection's loss closes, or
// why there is no current connection.
func (c *Conn) liveSession(method string) (<-chan struct{}, *rpc_RpcError) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	if failure := c.failure(method); failure != nil {
		return nil, failure
	}
	return c.session.Done(), nil
}

func (c *Conn) stateError(method string) *rpc_RpcError {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.failure(method)
}

// failure is why a call cannot be made now; the caller holds mu.
func (c *Conn) failure(method string) *rpc_RpcError {
	if c.disposed {
		return rpc_NewRpcError(rpc_CodeDisposed, "connection is disposed", method, nil)
	}
	if c.err != nil {
		return rpc_NewRpcError(c.err.Code, c.err.Message, method, nil)
	}
	if !c.live {
		return rpc_NewRpcError(rpc_CodeDisconnected, "socket is disconnected", method, nil)
	}
	return nil
}

// The server's default maxHttpBufferSize, assumed until a handshake reports
// the real limit.
const rpc_defaultMaxPayload = 1_000_000

// An upper bound on what a packet carries besides its JSON array: the
// Engine.IO and Socket.IO packet types, the namespace separator and an
// acknowledgement id of up to 20 digits.
const rpc_packetOverhead = 24

// checkPayload measures one outbound packet against the limit the server
// advertised in its handshake. Engine.IO closes the connection over a larger
// packet, failing every call in flight, so the one that is too large fails
// here on its own and nothing is sent.
func (c *Conn) checkPayload(method string, packet []any) *rpc_RpcError {
	payloadBytes := len(method)
	for _, item := range packet {
		if raw, ok := item.([]byte); ok {
			payloadBytes += len(raw)
			continue
		}
		encoded, err := rpc_encodeValue(item)
		if err != nil {
			return rpc_NewRpcError(rpc_CodeInternalError, fmt.Sprintf("cannot encode payload: %v", err), method, nil)
		}
		payloadBytes += len(encoded)
	}
	limit := int64(rpc_defaultMaxPayload)
	if engine, ok := c.socket.Io().Engine().(interface{ MaxPayload() int64 }); ok && engine.MaxPayload() > 0 {
		limit = engine.MaxPayload()
	}
	if size := int64(payloadBytes+len(c.namespace)) + rpc_packetOverhead; size > limit {
		message := fmt.Sprintf("payload of about %d bytes exceeds the %d bytes the server accepts", size, limit)
		return rpc_NewRpcError(rpc_CodeInvalidArgument, message, method, nil)
	}
	return nil
}

type rpc_ackResult struct {
	args []any
	err  error
}

func rpc_errorFromContext(ctx context.Context, method string) *rpc_RpcError {
	if ctx == nil {
		return rpc_NewRpcError(rpc_CodeInvalidArgument, "context must not be nil", method, nil)
	}
	if err := ctx.Err(); err != nil {
		if errors.Is(err, context.DeadlineExceeded) {
			return rpc_NewRpcError(rpc_CodeTimeout, err.Error(), method, nil)
		}
		return rpc_NewRpcError(rpc_CodeAborted, err.Error(), method, nil)
	}
	return nil
}

func rpc_errorFromTransport(err error, method string) *rpc_RpcError {
	if err == nil {
		return nil
	}
	if err.Error() == "operation has timed out" {
		return rpc_NewRpcError(rpc_CodeTimeout, err.Error(), method, nil)
	}
	if err.Error() == "socket has been disconnected" {
		return rpc_NewRpcError(rpc_CodeDisconnected, err.Error(), method, nil)
	}
	return rpc_NewRpcError(rpc_CodeInternalError, err.Error(), method, nil)
}

// emit performs one fire-and-forget call.
func rpc_emit(c *Conn, ctx context.Context, method string, args ...any) error {
	if err := rpc_errorFromContext(ctx, method); err != nil {
		return err
	}
	encoded, encErr := rpc_encodeArgs(method, args)
	if encErr != nil {
		return encErr
	}
	if err := c.checkPayload(method, encoded); err != nil {
		return err
	}
	c.emitState.mu.Lock()
	defer c.emitState.mu.Unlock()
	if err := c.stateError(method); err != nil {
		return err
	}
	if err := c.socket.NoBuffer().Emit(method, encoded...); err != nil {
		return rpc_errorFromTransport(err, method)
	}
	return nil
}

// request performs one acknowledged call and decodes the answer into target.
func rpc_request(c *Conn, ctx context.Context, method string, target any, args ...any) error {
	if err := rpc_errorFromContext(ctx, method); err != nil {
		return err
	}
	encoded, encErr := rpc_encodeArgs(method, args)
	if encErr != nil {
		return encErr
	}
	if err := c.checkPayload(method, encoded); err != nil {
		return err
	}
	response := make(chan rpc_ackResult, 1)
	c.emitState.mu.Lock()
	lost, err := c.liveSession(method)
	if err != nil {
		c.emitState.mu.Unlock()
		return err
	}
	c.socket.Timeout(c.timeout).NoBuffer().EmitWithAck(method, encoded...)(func(values []any, err error) {
		select {
		case response <- rpc_ackResult{args: values, err: err}:
		default:
		}
	})
	c.emitState.mu.Unlock()

	var acknowledged rpc_ackResult
	select {
	case <-ctx.Done():
		return rpc_errorFromContext(ctx, method)
	case <-c.done:
		return c.stateError(method)
	case <-lost:
		// The connection the call was sent on is gone, and the answer with it.
		// Dispose ends that connection too, after closing done, and says why.
		select {
		case <-c.done:
			return c.stateError(method)
		default:
		}
		return rpc_NewRpcError(rpc_CodeDisconnected, "connection lost before the call was acknowledged", method, nil)
	case acknowledged = <-response:
	}
	if acknowledged.err != nil {
		return rpc_errorFromTransport(acknowledged.err, method)
	}
	if len(acknowledged.args) != 1 {
		message := fmt.Sprintf("expected one acknowledgement value, got %d", len(acknowledged.args))
		return rpc_NewRpcError(rpc_CodeInvalidArgument, message, method, nil)
	}
	if failure, ok := rpc_decodeReplyError(acknowledged.args[0], method); ok {
		return failure
	}
	if err := rpc_decodeInto(acknowledged.args[0], target); err != nil {
		message := fmt.Sprintf("invalid acknowledgement payload: %v", err)
		return rpc_NewRpcError(rpc_CodeInvalidArgument, message, method, nil)
	}
	return nil
}

func (rpc_c *Conn) CallRegister(ctx context.Context, worker wire.Worker) (rpc_result wire.Registration, rpc_err error) {
	rpc_err = rpc_request(rpc_c, ctx, "register", &rpc_result, worker)
	return
}

func (rpc_c *Conn) CallProgress(ctx context.Context, taskID string, percent float64) error {
	return rpc_emit(rpc_c, ctx, "progress", taskID, percent)
}
